def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    total_players_alive = 1 + len(alive)
    expected_share = supply / float(total_players_alive) if total_players_alive > 0 else supply
    enough_if_even = expected_share >= WATER_REQ

    highest_prev = 0.0
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None and bid > highest_prev:
            highest_prev = float(bid)

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2
    if supply <= 16:
        danger += 2
    elif supply <= 18:
        danger += 1
    if not enough_if_even:
        danger += 1
    if urgent_opp >= 2:
        danger += 1
    if rich_opp >= 1:
        danger += 1

    if len(alive) == 0:
        base = DAILY_SALARY * 0.22
    elif danger >= 6:
        base = DAILY_SALARY * 0.98
    elif danger >= 4:
        base = DAILY_SALARY * 0.82
    elif danger >= 2:
        base = DAILY_SALARY * 0.58
    else:
        base = DAILY_SALARY * 0.34 if enough_if_even else DAILY_SALARY * 0.48

    if highest_prev >= DAILY_SALARY * 1.2:
        if danger <= 2:
            base = min(base, DAILY_SALARY * 0.35)
        else:
            base = max(base, DAILY_SALARY * 0.88)
    elif highest_prev >= DAILY_SALARY * 0.85:
        if danger <= 1:
            base = min(base, DAILY_SALARY * 0.32)
        else:
            base = max(base, highest_prev * 0.92)
    elif highest_prev > 0:
        target = highest_prev + 1.5
        if danger >= 3:
            base = max(base, target)
        else:
            base = max(base, min(target, DAILY_SALARY * 0.62))

    remaining_days = max(0, 10 - day)
    reserve_floor = remaining_days * DAILY_SALARY * 0.18
    affordable = max(0.0, budget - reserve_floor)
    if danger >= 4:
        affordable = budget

    bid = min(base, affordable if affordable > 0 else budget)

    if hp <= 1 or no_water >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.95))

    if day >= 8 and hp >= 5 and no_water == 0 and enough_if_even:
        bid = min(bid, DAILY_SALARY * 0.28)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units matter today (supply is total; water requirement is per day)
    # We only use this to scale bid pressure with supply.
    # If supply is low, winning water is more valuable.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))
    low_supply = 1.0 - supply_ratio

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Strategy:
    # - Cindy likely bids high; avoid matching her unless my hp is critical.
    # - If opponent yesterday bid was extremely high, increase slightly only when my hp is low.
    # - Otherwise bid a mid amount that should secure enough water without burning budget.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        pressure = 0.45
    elif highest_prev_bid > 0:
        pressure = 0.25

    # Base bid anchored to supply pressure and my hp
    # Keep bids below the likely top bidder unless survival is at stake.
    if hp <= 1.5:
        base = DAILY_SALARY * (0.85 + 0.1 * low_supply)
    elif hp <= 3.0:
        base = DAILY_SALARY * (0.65 + 0.15 * low_supply) + pressure * DAILY_SALARY * 0.15
    else:
        base = DAILY_SALARY * (0.45 + 0.10 * low_supply) + pressure * DAILY_SALARY * 0.10

    # If highest prev bid was very high, cap my bid to avoid overpaying.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        cap = highest_prev_bid * 0.55
    else:
        cap = DAILY_SALARY * 0.75

    bid = min(base, cap, budget)

    # Ensure non-negative and at least small bid if budget allows
    if bid < 0.0:
        bid = 0.0
    if budget > 0.0 and bid == 0.0:
        bid = min(budget, DAILY_SALARY * 0.15)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return max(1, min(budget, DAILY_SALARY * 0.4))

    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if supply <= 16:
        base_ratio = 0.6
    elif supply <= 20:
        base_ratio = 0.5
    else:
        base_ratio = 0.4

    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > 100:
            base_ratio = max(base_ratio, 0.7)
        elif max_prev > 80:
            base_ratio = max(base_ratio, 0.6)
        else:
            base_ratio = max(base_ratio, 0.45)

    if hp <= 2 or no_water_days > 0:
        base_ratio = min(base_ratio + 0.2, 0.95)

    bid = DAILY_SALARY * base_ratio
    bid = min(bid, budget)
    bid = max(1, bid)
    return bid
